      vinculo:   x.vinculo && x.vinculo.tipo ? { tipo:x.vinculo.tipo, id:x.vinculo.id } : null,
      obs:       x.obs || "",
      ignoradoMotivo:x.ignoradoMotivo||"",
      statusAtualizadoEm:x.statusAtualizadoEm||"",
