      fechadoPorId: f.fechadoPorId || "", fechadoPor: f.fechadoPor || "", fechadoEm: f.fechadoEm || "",
      reabertoPorId: f.reabertoPorId || "", reabertoPor: f.reabertoPor || "", reabertoEm: f.reabertoEm || "",
