function KpiCard({label,value,detail,icon,color=C.blue,onClick}){
  const displayValue=useCountUp(value);
  const Comp=onClick?"button":"div";
  return <Comp type={onClick?"button":undefined} onClick={onClick} className="dashboard-kpi" data-tone={semanticToneFromLegacyColor(color)} data-interactive={Boolean(onClick)}>
    <div className="dashboard-kpi__head">
      <span className="dashboard-kpi__label">{label}</span>
      <span className="dashboard-kpi__icon"><Ic n={icon} s={13}/></span>
    </div>
    <p className="dashboard-kpi__value">{displayValue}</p>
    {detail&&<p className="dashboard-kpi__detail">{detail}</p>}
  </Comp>;
}

// Cena de fundo do hero: única exceção ao sistema flat do DESIGN.md, porque
// aqui a ilustração carrega informação (a condição do tempo), não é
// decoração solta. Skyline + guindaste ficam sempre visíveis (silhueta de
// obra, sem preenchimento — mesma linguagem "blueprint" dos ícones e do
// mapa técnico do login); só a camada de clima muda com a condição real.
function HeroWeatherScene({icone}){
  if(!icone)return null;
  return <div className="dashboard-hero-scene" aria-hidden="true" style={{position:"absolute",inset:0,overflow:"hidden",borderRadius:C.rLg}}>
    <svg viewBox="0 0 600 200" preserveAspectRatio="xMidYMax slice" style={{position:"absolute",inset:0,width:"100%",height:"100%"}}>
      <rect x="0" y="0" width="600" height="200" className={`hero-scene-sky hero-scene-sky-${icone}`}/>

      {icone==="sun" && <g className="hero-scene-sun" style={{transformOrigin:"500px 55px"}}>
        <circle cx="500" cy="55" r="16" fill={`${C.yellow}22`} stroke="none" className="hero-scene-sun-glow"/>
        <circle cx="500" cy="55" r="24" fill="none" stroke={C.yellow} strokeWidth="2"/>
        {Array.from({length:8}).map((_,i)=>{
          const a=(i*45)*Math.PI/180, cx=500,cy=55;
          const x1=cx+Math.cos(a)*32,y1=cy+Math.sin(a)*32,x2=cx+Math.cos(a)*42,y2=cy+Math.sin(a)*42;
          return <line key={i} x1={x1} y1={y1} x2={x2} y2={y2} stroke={C.yellow} strokeWidth="2" strokeLinecap="round"/>;
        })}
      </g>}

      {(icone==="cloud"||icone==="cloudRain"||icone==="zap") && <>
        <path className="hero-scene-cloud hero-scene-cloud-a" d="M420 58h-8a22 22 0 1 0 0 44h60a16 16 0 0 0 0-32h-4a20 20 0 0 0-48-12z" fill="none" stroke={C.border} strokeWidth="2"/>
        <path className="hero-scene-cloud hero-scene-cloud-b" d="M495 36h-6a16 16 0 1 0 0 32h44a12 12 0 0 0 0-24h-3a15 15 0 0 0-35-8z" fill="none" stroke={C.border} strokeWidth="1.5" opacity=".7"/>
      </>}

      {(icone==="cloudRain"||icone==="zap") && <g className="hero-scene-rain">
        {[428,448,468,488,508,528].map((x,i)=><line key={x} className="hero-scene-drop" style={{"--drop-i":i}} x1={x} y1="108" x2={x-8} y2="126" stroke={C.blue} strokeWidth="2" strokeLinecap="round"/>)}
      </g>}

      {icone==="zap" && <path className="hero-scene-bolt" d="M474 66l-15 26h11l-13 24 24-28h-11z" fill={C.yellow}/>}

      <g className="hero-scene-skyline" stroke={C.line} strokeWidth="2" fill="none">
        <rect x="330" y="90" width="46" height="110"/>
        <rect x="384" y="60" width="56" height="140"/>
        <line x1="384" y1="90" x2="440" y2="90"/><line x1="384" y1="120" x2="440" y2="120"/><line x1="384" y1="150" x2="440" y2="150"/>
        <rect x="448" y="100" width="42" height="100"/>
        <line x1="330" y1="120" x2="376" y2="120"/><line x1="330" y1="150" x2="376" y2="150"/>
      </g>
      <g className="hero-scene-crane" stroke={C.subtle} strokeWidth="2" fill="none" strokeLinecap="round">
        <line x1="300" y1="200" x2="300" y2="40"/>
        <line x1="270" y1="42" x2="360" y2="42"/>
        <line x1="300" y1="55" x2="270" y2="42"/>
        <line x1="300" y1="55" x2="345" y2="60"/>
        <line x1="345" y1="42" x2="345" y2="60"/>
      </g>
    </svg>
    <div className="dashboard-hero-scene-fade" style={{position:"absolute",inset:0}}/>
  </div>;
}

function DashboardTechHero({data,currentUser,ultimaSync,fila,onBuscar,onAtualizar,onAbrir,periodo,onAnterior,onProximo,proximoDesabilitado,clima,saveState=SAVE_QUEUE_STATE.IDLE}){
  const {isDesktop}=useBreakpoint();
  const agora=new Date(),nome=(currentUser?.nome||"operador").trim().split(/\s+/)[0];
  const saudacao=agora.getHours()<12?"Bom dia":agora.getHours()<18?"Boa tarde":"Boa noite";
  const papel=ROLES.find(r=>r.v===currentUser?.role)?.l||"Operador";
  const criticas=fila.filter(x=>x.severidade===3).length;
  const mensagem=criticas
    ? `Vamos priorizar ${criticas} ${criticas===1?"ponto crítico":"pontos críticos"} agora.`
    : fila.length
      ? `Seu dia está organizado em ${fila.length} ${fila.length===1?"ação":"ações"} objetivas.`
      : "A operação está em ordem. Bom trabalho hoje.";
  // Leitura do clima para decisão de campo: condição, vento e UV viram uma
  // frase objetiva sobre atividade externa/concretagem, com uma piada leve
  // no fim — não só o número.
  const climaObra=clima&&{
    sun:      {condicao:"ensolarado",piada:"Sol favorece o cronograma — só não esqueça o protetor solar do time.",cor:C.yellowD},
    cloud:    {condicao:"nublado",piada:"Tempo ameno, sem desculpa de calor pra atrasar nada hoje.",cor:C.subtle},
    cloudRain:{condicao:"chuvoso",piada:"Bom dia pra revisar planilha, ruim pra concretar.",cor:C.orange},
    zap:      {condicao:"com trovoada",piada:"Hoje o café do escritório rende mais que o canteiro.",cor:C.red},
  }[clima.icone];
  const climaTxt=climaObra&&`Hoje o clima em Caruaru está ${climaObra.condicao}, ${clima.temperatura}°, ventos a ${clima.vento} km/h${clima.uv!=null?`, índice UV ${clima.uv}${clima.uvLabel?` (${clima.uvLabel})`:""}`:""}. ${climaObra.piada}`;
  const syncInfo={
    [SAVE_QUEUE_STATE.IDLE]:{label:"sincronizado",color:C.green},
    [SAVE_QUEUE_STATE.SAVING]:{label:"salvando alterações",color:C.yellowD},
    [SAVE_QUEUE_STATE.RETRY_SCHEDULED]:{label:"nova tentativa agendada",color:C.orange},
    [SAVE_QUEUE_STATE.OFFLINE]:{label:"alterações aguardando conexão",color:C.orange},
    [SAVE_QUEUE_STATE.CONFLICT]:{label:"conflito aguardando resolução",color:C.red},
    [SAVE_QUEUE_STATE.FAILED]:{label:"alterações não sincronizadas",color:C.red},
  }[saveState]||{label:"sincronizado",color:C.green};
  return <section className="dashboard-tech-hero" style={{position:"relative",overflow:"hidden",minHeight:isDesktop?178:232,borderRadius:C.rLg,padding:isDesktop?"20px 22px":"18px",color:C.text,background:C.card,border:`1px solid ${C.border}`,boxShadow:"none"}}>
    <HeroWeatherScene icone={clima?.icone}/>
    <span className="dashboard-hero-rule" aria-hidden="true" style={{position:"absolute",top:0,left:0,right:0,height:2,background:C.yellow}}/>
    <div style={{position:"relative",zIndex:1,display:"flex",flexDirection:"column",minHeight:isDesktop?136:196,justifyContent:"space-between",gap:14}}>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",gap:12}}><div><div style={{display:"flex",alignItems:"center",gap:8}}><span style={{width:7,height:7,borderRadius:99,background:syncInfo.color}}/><span style={{fontSize:9,fontWeight:850,letterSpacing:1.6,textTransform:"uppercase",color:C.yellowD}}>ARCD Operational Intelligence · {syncInfo.label}</span></div><p style={{fontSize:10,color:C.muted,marginTop:7}}>{papel} · {syncInfo.label}{saveState===SAVE_QUEUE_STATE.IDLE?(ultimaSync?` às ${ultimaSync.toLocaleTimeString("pt-BR",{hour:"2-digit",minute:"2-digit"})}`:" agora"):""}</p></div><div style={{display:"flex",alignItems:"center",gap:6}}>{onBuscar&&<Btn v="ghost" iconOnly onClick={onBuscar} title="Buscar" ariaLabel="Buscar"><Ic n="funnel" s={13}/></Btn>}{onAtualizar&&<Btn v="ghost" iconOnly onClick={onAtualizar} title="Atualizar" ariaLabel="Atualizar"><Ic n="refresh" s={13}/></Btn>}</div></div>
      <div className="dashboard-greeting" style={{maxWidth:640}}>
        <p style={{fontSize:9,textTransform:"uppercase",letterSpacing:1.2,color:C.yellowD,fontWeight:800}}>{agora.toLocaleDateString("pt-BR",{weekday:"long",day:"2-digit",month:"long"})}</p>
        <h1 style={{...TYPO.h1,fontSize:"clamp(24px,3vw,32px)",marginTop:5}}>{saudacao}, {nome}.</h1>
        {climaObra&&<p style={{fontSize:13.5,lineHeight:1.5,marginTop:9,color:C.subtle}}><span aria-hidden="true" className={`dashboard-weather-motif dashboard-weather-motif-${clima.icone}`} style={{display:"inline-flex",verticalAlign:"-5px",marginRight:3}}><Ic n={clima.icone} s={18} color={climaObra.cor}/></span>{climaTxt}</p>}
        <p style={{fontSize:13,fontWeight:750,marginTop:7,color:C.yellowD}}>{mensagem}</p>
      </div>
      <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:9,flexWrap:"wrap"}}><div style={{display:"flex",alignItems:"center",gap:9,flexWrap:"wrap"}}><Btn v="primary" onClick={()=>fila[0]&&onAbrir(fila[0].tab)} disabled={!fila.length}>{fila.length?`Abrir prioridade principal →`:"Nenhuma ação urgente"}</Btn><span style={{fontSize:10,color:C.muted}}><b style={{color:criticas?C.red:C.green}}>{criticas}</b> crítica(s) · <b style={{color:C.yellowD}}>{fila.length}</b> missão(ões) ativa(s)</span></div>{periodo&&<div style={{display:"flex",alignItems:"center",border:`1px solid ${C.border}`,background:C.card2,borderRadius:9,padding:2}}><button onClick={onAnterior} style={{border:0,background:"transparent",color:C.subtle,padding:"5px 8px",cursor:"pointer"}}>←</button><span style={{minWidth:100,textAlign:"center",fontSize:9.5,fontWeight:750,textTransform:"capitalize",color:C.muted}}>{periodo}</span><button onClick={onProximo} disabled={proximoDesabilitado} style={{border:0,background:"transparent",color:proximoDesabilitado?C.cinza:C.subtle,padding:"5px 8px",cursor:proximoDesabilitado?"default":"pointer"}}>→</button></div>}</div>
    </div>
  </section>;
}

function FilaOperador({fila,onTab}){
  const [filtro,setFiltro]=useState("todas");
  const setores=[...new Set(fila.map(x=>x.setor))];
  const lista=filtro==="todas"?fila:fila.filter(x=>x.setor===filtro);
  return <section id="dashboard-missoes" className="dashboard-mission-queue" style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:C.rLg,overflow:"hidden",boxShadow:"none"}}>
    <div style={{padding:"14px 16px",display:"flex",justifyContent:"space-between",alignItems:"center",gap:10,flexWrap:"wrap",borderBottom:`1px solid ${C.line}`}}>
      <div><p style={TYPO.eyebrow}>Prioridades por responsabilidade</p><h3 style={{...TYPO.h3,marginTop:3}}>Central de ações</h3></div>
      <div style={{display:"flex",gap:4,overflowX:"auto",maxWidth:"100%"}}>{["todas",...setores].map(s=><button key={s} onClick={()=>setFiltro(s)} data-active={filtro===s} style={{border:`1px solid ${filtro===s?C.yellow:C.border}`,background:filtro===s?`${C.yellow}1F`:"transparent",color:filtro===s?C.yellowD:C.muted,borderRadius:99,padding:"5px 9px",fontSize:9,fontWeight:750,cursor:"pointer",whiteSpace:"nowrap"}}>{s==="todas"?"Todas":s}</button>)}</div>
    </div>
    {!lista.length
      ? <div style={{padding:25,textAlign:"center",color:C.green,fontSize:11}}><Ic n="check" color={C.green}/> Nenhuma pendência no seu escopo.</div>
      : <div className="dashboard-mission-rows" style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(280px,1fr))"}}>{lista.map((m,i)=>{const cor=m.severidade===3?C.red:m.color||C.yellow;return <button key={m.id} onClick={()=>onTab(m.tab)} style={{"--row-i":i,display:"grid",gridTemplateColumns:"38px minmax(0,1fr) auto",alignItems:"center",gap:10,textAlign:"left",border:0,borderRight:`1px solid ${C.line}`,borderBottom:`1px solid ${C.line}`,background:"transparent",padding:"13px 15px",cursor:"pointer",color:C.text}}><span style={{width:36,height:36,borderRadius:9,display:"grid",placeItems:"center",background:`${cor}12`,border:`1px solid ${cor}35`,color:cor}}><Ic n={m.icon} s={15} color={cor}/></span><span style={{minWidth:0}}><b style={{display:"block",fontSize:11.5,fontWeight:760,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{m.titulo}</b><small style={{display:"block",fontSize:9.5,color:C.muted,marginTop:3,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{m.detalhe}</small></span><span style={{minWidth:27,height:27,borderRadius:9,display:"grid",placeItems:"center",fontSize:10,fontWeight:900,color:cor,background:`${cor}12`}}>{m.quantidade}</span></button>;})}</div>}
  </section>;
}

// Lista de notícias genérica (setor nacional ou regional CBIC/Sinduscon-PE):
