function WorkerMovementModal({ data, showToast, employee, initialMode = "transfer", onClose, dispatchAttendanceCommand, dispatchCommand }) {
  const { formGrid } = useBreakpoint();
  const [mode, setMode] = useState(initialMode);
  const [newObra, setNewObra] = useState("");
  const [endDate, setEndDate] = useState(today());
  const [reason, setReason] = useState("Demitido");

  const activeObras = data.obras.filter(o => o.status !== "done");
  const obraName = id => data.obras.find(o => o.id === id)?.name || "-";

  const saveTransfer = async () => {
    if (!newObra) {
      showToast("Selecione a nova obra.", "error");
      return;
    }
    if (!employee.obra) {
      showToast("Este trabalhador não tem obra atual definida. Edite o cadastro dele na aba Equipe.", "error");
      return;
    }
    if (newObra === employee.obra) {
      showToast("Selecione uma obra diferente da atual.", "error");
      return;
    }
    const obraDestino = data.obras.find(o => o.id === newObra);
    if (!obraDestino) {
      showToast("Obra de destino não encontrada. Atualize a página.", "error");
      return;
    }

    const to = obraName(newObra);
    const saved=await dispatchCommand(atual=>{
      const vigente=(atual.employees||[]).find(item=>item.id===employee.id);
      return {
        type:OPERATIONAL_COMMAND.EMPLOYEE_SAVED,
        idempotencyKey:`funcionario-transferir-${employee.id}-${uid()}`,
        expectedVersion:Number(employee.version||0),
        payload:{employee:{
          ...vigente,
          obra:newObra,
          lastObra:vigente?.obra||vigente?.lastObra||"",
          obraHistory:[...(vigente?.obraHistory||[]),{
            date:today(),fromObraId:vigente?.obra||"",toObraId:newObra,
          }],
          active:true,
          endDate:"",
          terminationReason:"",
        }},
      };
    });
    if(!saved?.ok){showToast(saved?.reason||"A transferência não foi confirmada pelo servidor.","error");return;}
    const checked=await dispatchAttendanceCommand({
      action:"attendance-daily-check",operationId:pointOperationId(),date:today(),
    });
    if(!checked?.ok){showToast(checked?.reason||"A transferência foi salva, mas a conferência diária não foi confirmada.","error");return;}
    showToast(`${employee.name} transferido para ${to}.`);
    onClose();
  };

  const saveDismissal = async () => {
    if (!endDate) {
      showToast("Informe a data de término.", "error");
      return;
    }

    if(endDate<employee.startDate){showToast("O último dia não pode anteceder a admissão.","error");return;}
    const scheduled=endDate>today();
    const saved=await dispatchCommand(atual=>{
      const vigente=(atual.employees||[]).find(item=>item.id===employee.id);
      return {
        type:OPERATIONAL_COMMAND.EMPLOYEE_SAVED,
        idempotencyKey:`funcionario-demitir-${employee.id}-${uid()}`,
        expectedVersion:Number(employee.version||0),
        payload:{employee:{
          ...vigente,
          active:scheduled,
          status:scheduled?"desligamento_agendado":"desligado",
          endDate,
          terminationReason:reason||"Demitido",
          lastObra:vigente?.obra||vigente?.lastObra||"",
        }},
      };
    });
    if(!saved?.ok){showToast(saved?.reason||"A demissão não foi confirmada pelo servidor.","error");return;}
    const checked=await dispatchAttendanceCommand({
      action:"attendance-daily-check",operationId:pointOperationId(),date:today(),
    });
    if(!checked?.ok){showToast(checked?.reason||"A demissão foi salva, mas a conferência diária não foi confirmada.","error");return;}
    showToast(scheduled?`Desligamento agendado. Último dia trabalhado: ${fmtDateFull(endDate)}.`:`${employee.name} desligado. Último dia trabalhado: ${fmtDateFull(endDate)}.`);
    onClose();
  };

  return (
    <Modal title={mode === "transfer" ? "Transferir trabalhador" : "Registrar desligamento"} onClose={onClose}>
      <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
        <div style={{ background: C.card, border: `1px solid ${C.border}`, borderLeft: `4px solid ${mode === "transfer" ? C.yellow : C.red}`, padding: 12 }}>
          <p style={{ fontFamily:"'Inter Display','Inter',sans-serif", fontWeight: 900, fontSize: 18 }}>{employee.name}</p>
          <p style={{ color: C.muted, fontSize: 12 }}>Obra atual: {obraName(employee.obra)}{employee.role ? `  ${employee.role}` : ""}</p>
        </div>
        <div style={{ display: "grid", gridTemplateColumns:formGrid(2), gap: 8 }}>
          <Btn v={mode === "transfer" ? "warning" : "ghost"} onClick={() => setMode("transfer")} full>Transferir</Btn>
          <Btn v={mode === "dismiss" ? "danger" : "ghost"} onClick={() => setMode("dismiss")} full>Desligar</Btn>
        </div>
        {mode === "transfer" ? (
          <Sel label="Nova obra *" value={newObra} onChange={setNewObra} options={[{ v: "", l: "Selecione" }, ...activeObras.filter(o => o.id !== employee.obra).map(o => ({ v: o.id, l: o.name }))]} />
        ) : (
          <>
            <Inp label="Data de término *" type="date" value={endDate} onChange={setEndDate} />
            <Inp label="Motivo" value={reason} onChange={setReason} />
          </>
        )}
        <div style={{ display: "flex", gap: 8 }}>
          <Btn v="ghost" onClick={onClose} full>Cancelar</Btn>
          <Btn v={mode === "transfer" ? "warning" : "danger"} onClick={mode === "transfer" ? saveTransfer : saveDismissal} full>
            <Ic n="check" /> {mode === "transfer" ? "Confirmar transferência" : "Confirmar demissão"}
          </Btn>
        </div>
      </div>
    </Modal>
  );
}

function UnlockRequestModal({ data, dispatchAttendanceCommand, showToast, obraId, date, employee, onClose }) {
  const [reason, setReason] = useState("");
  const obra = data.obras.find(o => o.id === obraId);
  const obraName = obra?.name || "-";
  const approverEmail = data.config.approverEmail || "hygorlp@gmail.com";

  const sendRequest = async () => {
    if (!reason.trim()) {
      showToast("Informe o motivo da solicitação.", "error");
      return;
    }

    const requestId = pointOperationId();
    const approvalLink = `${window.location.origin}${window.location.pathname}?approve_unlock=${encodeURIComponent(requestId)}`;
    const result=await dispatchAttendanceCommand({
      action:"attendance-unlock-request",operationId:requestId,requestId,obraId,date,
      employeeId:employee?.id||"",reason,
    });
    if(!result?.ok){showToast(result?.reason||"A solicitação não foi registrada.","error");return;}

    window.location.href = buildPermissionEmail({
      to: approverEmail,
      obraName,
      date,
      employeeName: employee?.name || "",
      reason,
      approvalLink,
    });

    showToast("Solicitação registrada no servidor e e-mail preparado.");
    onClose();
  };

  return (
    <Modal title="Solicitar permissão" onClose={onClose}>
      <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
        <div style={{ background: C.card, border: `1px solid ${C.border}`, borderLeft: `4px solid ${C.yellow}`, padding: 12 }}>
          <p style={{ fontFamily:"'Inter Display','Inter',sans-serif", fontWeight: 900, fontSize: 18 }}>{obraName}</p>
          <p style={{ color: C.muted, fontSize: 12 }}>Data bloqueada: {fmtDateFull(date)}</p>
          {employee?.name && <p style={{ color: C.muted, fontSize: 12 }}>Trabalhador: {employee.name}</p>}
          <p style={{ color: C.subtle, fontSize: 12, marginTop: 6 }}>A solicitação será enviada para {approverEmail}.</p>
        </div>
        <Inp label="Motivo da alteração *" value={reason} onChange={setReason} multiline placeholder="Ex.: ponto lançado errado, funcionário em obra diferente, ajuste solicitado pelo responsável..." />
        <div style={{ display: "flex", gap: 8 }}>
          <Btn v="ghost" onClick={onClose} full>Cancelar</Btn>
          <Btn v="warning" onClick={sendRequest} full><Ic n="mail" /> Enviar solicitação</Btn>
        </div>
      </div>
    </Modal>
  );
}

// 
// Ponto
// 

function PontoGeral({ data, update, showToast, currentUser, onTab, dispatchAttendanceCommand }) {
  const agora = new Date();
  const refInicial = agora.getDate() <= 5 ? new Date(agora.getFullYear(), agora.getMonth()-1, 1) : agora;
  const [year,setYear]=useState(refInicial.getFullYear());
  const [month,setMonth]=useState(refInicial.getMonth());
  const [q,setQ]=useState(agora.getDate()>=6&&agora.getDate()<=20?"1":"2");
  const [filterObra,setFilterObra]=useState("all");
  const [busca,setBusca]=useState("");
  const [obraCell,setObraCell]=useState(null);   // "empId::date" da célula com troca de obra aberta
  const pendingCellsRef=useRef(new Map());
  const [,setPendingCellsRevision]=useState(0);
  const {q1,q2}=getQ(year,month);
  const diasCiclo=q==="1"?q1:q2;

  // ── Quinzena arquivada ──────────────────────────────────────────
  // Depois que o RH confere e paga, a quinzena e movida para uma linha
  // propria no banco (o JSON principal encolhe e o save fica leve). A
  // quinzena arquivada fica bloqueada aqui; consulta e feita sob demanda.
  const quinzenaId=`${year}-${String(month+1).padStart(2,"0")}-Q${q}`;
  const quinzenaLabel=`${q==="1"?"1ª":"2ª"} quinzena de ${MONTHS[month]}/${year}`;
  const arqMeta=(data.quinzenasArquivadas||{})[quinzenaId];
  const podeArquivar=currentUser?.role==="admin"||currentUser?.role==="rh";
  const quinzenaEncerrada=diasCiclo[diasCiclo.length-1]<today();
  const [arqBusy,setArqBusy]=useState(false);
  const [arqView,setArqView]=useState(null);   // conteudo do arquivo aberto no modal

  const bloqueadoPorArquivo=()=>{
    if(!arqMeta)return false;
    showToast("Esta quinzena está finalizada e arquivada. Só o administrador pode restaurá-la para edição.","error");
    return true;
  };

  const finalizarQuinzena=async()=>{
    let total=0;const empsEnvolvidos=new Set();
    Object.entries(data.attendance||{}).forEach(([empId,mapa])=>{
      diasCiclo.forEach(d=>{if(mapa?.[d]){total++;empsEnvolvidos.add(empId);}});
    });
    if(!total){showToast("Não há lançamentos nesta quinzena para arquivar.","error");return;}
    const aviso=[
      `FINALIZAR E ARQUIVAR a ${quinzenaLabel}?`,
      "",
      `- ${total} lançamento(s) de ${empsEnvolvidos.size} funcionário(s)`,
      "- O ponto sai do sistema principal e vira um arquivo próprio",
      "- A quinzena fica BLOQUEADA para edição (só o admin restaura)",
      "",
      "Faça isso somente APÓS conferir e pagar a folha desta quinzena."
    ].join("\n");
    if(!window.confirm(aviso))return;
    const sincronizado=await update({__aguardarFila:true});
    if(!sincronizado?.ok){showToast("Conclua o conflito de salvamento antes de arquivar a quinzena.","error");return;}
    setArqBusy(true);
    const r=await arquivarQuinzena({quinzenaId,label:quinzenaLabel,dates:diasCiclo});
    setArqBusy(false);
    if(!r.ok){showToast(r.erro||"Falha ao arquivar.","error");return;}
    update({__adotarServidor:true,data:r.data,updatedAt:r.updatedAt});
    showToast(`Quinzena finalizada e arquivada (${r.meta?.totalLancamentos||total} lançamento(s)).`);
  };

  const verArquivo=async()=>{
    setArqBusy(true);
    const r=await carregarQuinzenaArquivada(quinzenaId);
    setArqBusy(false);
    if(!r.ok){showToast(r.erro||"Falha ao abrir o arquivo.","error");return;}
    setArqView(r.arquivo);
  };

  const restaurarArquivo=async()=>{
    if(!window.confirm(`Restaurar a ${quinzenaLabel}?\n\nOs lançamentos voltam ao ponto principal e a quinzena reabre para edição. Dias relançados depois do arquivamento são mantidos como estão.`))return;
    const sincronizado=await update({__aguardarFila:true});
    if(!sincronizado?.ok){showToast("Conclua o conflito de salvamento antes de restaurar a quinzena.","error");return;}
    setArqBusy(true);
    const r=await restaurarQuinzena(quinzenaId);
    setArqBusy(false);
    if(!r.ok){showToast(r.erro||"Falha ao restaurar.","error");return;}
    setArqView(null);
    update({__adotarServidor:true,data:r.data,updatedAt:r.updatedAt});
    showToast(`Quinzena restaurada: ${r.devolvidos} lançamento(s) devolvido(s)${r.mantidos?`, ${r.mantidos} mantido(s)`:""}.`);
  };
  // A gestao mostra somente segunda a sexta. Feriados em dias uteis
  // permanecem sempre visiveis e destacados, mesmo sem lancamento.
  const days=diasCiclo.filter(prIsWeekdayIso);
  const feriados=prUniqueDates([...new Set(diasCiclo.map(d=>Number(d.slice(0,4))))].flatMap(ano=>getPayrollHolidays(data,ano)));
  const obraName=id=>(data.obras||[]).find(o=>o.id===id)?.name||"-";
  const obraDoRegistro=(employee,date,record,selectedObraId="")=>resolveEmployeeAttendanceObraId({
    data,employee,date,record,selectedObraId,
  });
  const employees=(data.employees||[]).filter(e=>employeeRelevantInPeriod(data,e,diasCiclo))
    .filter(e=>filterObra==="all"||e.obra===filterObra||e.lastObra===filterObra||days.some(d=>obraDoRegistro(e,d,getAtt(data,e.id,d))===filterObra))
    .filter(e=>[e.name,e.role,obraName(e.obra)].join(" ").toLowerCase().includes(busca.toLowerCase()))
    .sort((a,b)=>a.name.localeCompare(b.name));
  const diaLabel=iso=>{const d=prParseIso(iso);return `${String(d.getDate()).padStart(2,"0")}/${String(d.getMonth()+1).padStart(2,"0")}`;};
  const semana=iso=>["DOM","SEG","TER","QUA","QUI","SEX","SÁB"][prParseIso(iso).getDay()];
  const corStatus=st=>st==="P"?C.green:st==="M"?C.yellow:st==="F"?C.red:C.muted;
  const proxStatus=st=>st==="P"?"M":st==="M"?"F":st==="F"?null:"P";
  const cellKeyFor=(employeeId,date)=>`${employeeId}::${date}`;
  const attendanceFor=(employeeId,date)=>{
    const pending=pendingCellsRef.current.get(cellKeyFor(employeeId,date));
    return pending?pending.record:getAtt(data,employeeId,date);
  };
  const markPending=(operationId,patches)=>{
    patches.forEach(patch=>pendingCellsRef.current.set(cellKeyFor(patch.employeeId,patch.date),{
      operationId,
      record:patch.record,
    }));
    setPendingCellsRevision(value=>value+1);
  };
  const clearPending=(operationId,patches)=>{
    let changed=false;
    patches.forEach(patch=>{
      const key=cellKeyFor(patch.employeeId,patch.date);
      if(pendingCellsRef.current.get(key)?.operationId!==operationId)return;
      pendingCellsRef.current.delete(key);
      changed=true;
    });
    if(changed)setPendingCellsRevision(value=>value+1);
  };

  const salvarCelula=async(emp,date,patch)=>{
    if(bloqueadoPorArquivo())return;
    const anterior=attendanceFor(emp.id,date)||{status:null,ot:0,note:"",obraId:""};
    const novo={...anterior,...patch};
    const obraId=obraDoRegistro(emp,date,novo,patch.obraId);
    if(obraId&&!canEditAttendance(data,obraId,date,currentUser?.id)){
      showToast(`O ponto de ${obraName(obraId)} em ${fmtDateFull(date)} está bloqueado. Libere-o no Ponto diário.`,"error");return;
    }
    const operationId=pointOperationId();
    const patches=[{employeeId:emp.id,date,record:{...novo,obraId}}];
    markPending(operationId,patches);
    const result=await dispatchAttendanceCommand({
      action:"attendance-upsert",operationId,employeeId:emp.id,date,
      selectedObraId:patch.obraId||obraId,
      record:{...novo,obraId},
    });
    clearPending(operationId,patches);
    if(!result?.ok)showToast(result?.reason||"O ponto não foi salvo.","error");
  };

  // Sem preenchimento automático de presença: cada dia é marcado manualmente,
  // clicando na própria célula - evita presença lançada sem verificação real.
  const limparLinha=async emp=>{
    if(bloqueadoPorArquivo())return;
    if(!window.confirm(`Limpar os lançamentos visíveis de ${emp.name}?`))return;
    let bloqueados=0;
    const patches=days.flatMap(date=>{
      const ant=getAtt(data,emp.id,date);
      if(!ant)return [];
      const obraId=obraDoRegistro(emp,date,ant);
      if(obraId&&!canEditAttendance(data,obraId,date,currentUser?.id)){bloqueados++;return [];}
      return [{employeeId:emp.id,date,selectedObraId:obraId,record:{...ant,status:null,obraId}}];
    });
    if(!patches.length){
      showToast(bloqueados?"Os lançamentos visíveis estão bloqueados.":"Não há lançamentos para limpar.",bloqueados?"error":"success");
      return;
    }
    const operationId=pointOperationId();
    markPending(operationId,patches);
    const result=await dispatchAttendanceCommand({
      action:"attendance-batch-upsert",operationId,patches,
    });
    clearPending(operationId,patches);
    if(!result?.ok){showToast(result?.reason||"Os lançamentos não foram removidos.","error");return;}
    showToast(bloqueados?`${bloqueados} dia(s) bloqueado(s) foram preservados; os demais foram removidos.`:"Lançamentos do período removidos.");
  };

  const periodo=`${fmtDateFull(diasCiclo[0])} a ${fmtDateFull(diasCiclo[diasCiclo.length-1])}`;
  const rotuloCurto=st=>st==="P"?"P":st==="M"?"½":st==="F"?"F":"·";
  return <div className="anim ponto-geral" style={{display:"flex",flexDirection:"column",gap:12}}>
    <PageHero
      eyebrow="Gestão do ponto"
      title="Ponto da quinzena"
      description={`${periodo} · ${employees.length} funcionário(s)`}
    />

    <div className="ponto-geral-controls">
      <div className="ponto-geral-filters">
        <Sel label="Ciclo" value={q} onChange={setQ} options={[{v:"1",l:"1ª quinzena · 06 a 20"},{v:"2",l:"2ª quinzena · 21 a 05"}]}/>
        <Sel label="Mês" value={String(month)} onChange={v=>setMonth(Number(v))} options={MONTHS.map((m,i)=>({v:String(i),l:m}))}/>
        <Inp label="Ano" type="number" value={year} onChange={v=>setYear(Number(v)||agora.getFullYear())}/>
        <Sel label="Obra" value={filterObra} onChange={setFilterObra} options={[{v:"all",l:"Todas as obras"},...(data.obras||[]).map(o=>({v:o.id,l:o.name}))]}/>
        <Inp label="Buscar funcionário" value={busca} onChange={setBusca} placeholder="Nome, cargo ou obra..."/>
      </div>
      <p className="ponto-geral-count">{employees.length} funcionário(s) neste filtro · marcação dia a dia, clicando na célula</p>
    </div>

    {arqMeta ? (
      <div className="ponto-geral-archive" style={{background:`${C.yellow}10`,border:`1px solid ${C.yellow}`,borderRadius:8,padding:"10px 14px",display:"flex",justifyContent:"space-between",alignItems:"center",gap:10,flexWrap:"wrap"}}>
        <div>
          <p style={{fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:900,fontSize:13,color:C.yellowD,display:"flex",alignItems:"center",gap:6}}><Ic n="lock"/> QUINZENA FINALIZADA E ARQUIVADA</p>
          <p style={{fontSize:11,color:C.muted,marginTop:2}}>
            {arqMeta.totalLancamentos} lançamento(s) de {arqMeta.funcionarios} funcionário(s) · arquivada por {arqMeta.archivedBy?.nome||"-"} em {fmtDateFull(String(arqMeta.archivedAt||"").slice(0,10))}. Edição bloqueada.
          </p>
        </div>
        <div style={{display:"flex",gap:6,flexWrap:"wrap"}}>
          <Btn v="ghost" size="sm" onClick={verArquivo} disabled={arqBusy}><Ic n="calendar"/> Ver arquivo</Btn>
          {currentUser?.role==="admin"&&<Btn v="warning" size="sm" onClick={restaurarArquivo} disabled={arqBusy}><Ic n="unlock"/> Restaurar</Btn>}
        </div>
      </div>
    ) : podeArquivar ? (
      <div className="ponto-geral-archive" style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:8,padding:"10px 14px",display:"flex",justifyContent:"space-between",alignItems:"center",gap:10,flexWrap:"wrap"}}>
        <p style={{fontSize:11,color:C.muted}}>
          {quinzenaEncerrada
            ? "Após conferir e pagar a folha, finalize a quinzena: o ponto vira um arquivo próprio, a edição é bloqueada e o sistema fica mais leve."
            : "A quinzena ainda está em andamento. Finalize somente após o último dia do ciclo e o pagamento da folha."}
        </p>
        <Btn v="warning" size="sm" onClick={finalizarQuinzena} disabled={arqBusy||!quinzenaEncerrada}
          title={quinzenaEncerrada?"":"Disponível após o fim da quinzena"}>
          <Ic n="lock"/> {arqBusy?"Arquivando...":"Finalizar e arquivar quinzena"}
        </Btn>
      </div>
    ) : null}

    <div className="ponto-geral-legend">
      <span className="ponto-legend-title">Clique na célula para alternar</span>
      <span className="ponto-legend-chip"><i style={{background:C.green}}/>Presente</span>
      <span className="ponto-legend-chip"><i style={{background:C.yellowD}}/>Meio dia</span>
      <span className="ponto-legend-chip"><i style={{background:C.red}}/>Falta</span>
      <span className="ponto-legend-chip"><i style={{background:C.cinza}}/>Sem registro</span>
      <span className="ponto-legend-help">Para mudar a obra do dia, clique no texto abaixo do status.</span>
    </div>

    <div className="ponto-geral-table-wrap" style={{overflow:"auto",border:`1px solid ${C.border}`,borderRadius:8,background:C.card,maxHeight:"70vh"}}>
      <table className="ponto-geral-table" style={{borderCollapse:"separate",borderSpacing:0,minWidth:Math.max(900,354+days.length*64),width:"100%",fontSize:10}}>
        <thead style={{position:"sticky",top:0,zIndex:5}}><tr>
          <th className="ponto-col-funcionario" style={{position:"sticky",left:0,zIndex:7,minWidth:290,background:C.surface,color:C.text,padding:"8px 12px",textAlign:"left",fontSize:9.5,fontWeight:800,letterSpacing:.4,borderBottom:`1px solid ${C.border}`}}>FUNCIONÁRIO E AÇÕES</th>
          <th className="ponto-col-total" style={{minWidth:64,background:C.surface,color:C.text,padding:8,fontSize:9.5,fontWeight:800,borderBottom:`1px solid ${C.border}`}}>DIAS</th>
          {days.map(date=>{const feriado=feriados.includes(date);return <th className="ponto-col-dia" key={date} title={feriado?"Feriado cadastrado":""} style={{minWidth:64,background:feriado?`${C.red}14`:C.surface,color:feriado?C.red:C.text,padding:"6px 4px",borderLeft:`1px solid ${C.line}`,borderBottom:`1px solid ${C.border}`}}><div style={{fontSize:10,fontWeight:800}}>{diaLabel(date)}</div><div style={{fontSize:7.5,fontWeight:feriado?900:600,opacity:feriado?1:.6}}>{feriado?"FER":semana(date)}</div></th>;})}
        </tr></thead>
        <tbody>{employees.map(emp=>{const equivalentes=days.reduce((s,d)=>{const st=attendanceFor(emp.id,d)?.status;return s+(st==="P"?1:st==="M"?.5:0);},0);return <tr key={emp.id} style={{borderTop:`1px solid ${C.line}`}}>
          <td className="ponto-col-funcionario" style={{position:"sticky",left:0,zIndex:2,background:C.card,padding:"8px 12px",borderTop:`1px solid ${C.line}`,minWidth:290}}>
            <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",gap:10}}>
              <div style={{minWidth:0}}>
                <div style={{display:"flex",alignItems:"center",gap:5,minWidth:0}}>
                  <button type="button" onClick={()=>{window.sessionStorage.setItem("arcd_editar_funcionario",emp.id);onTab?.("equipe");}} title="Editar cadastro do funcionário" style={{fontSize:11,fontWeight:800,color:C.text,display:"block",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap",cursor:"pointer",border:0,background:"transparent",padding:0,textAlign:"left",textDecoration:"underline",textDecorationColor:"transparent",textUnderlineOffset:2}} onMouseEnter={e=>e.currentTarget.style.textDecorationColor=C.blue} onMouseLeave={e=>e.currentTarget.style.textDecorationColor="transparent"}>{emp.name}</button>
                  {emp.active===false&&<Badge color={C.muted}>Demitido</Badge>}
                </div>
                <div style={{fontSize:8.5,color:C.muted,marginTop:1,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{emp.role||"Funcionário"} · {obraName(emp.obra)}</div>
              </div>
              <div className="ponto-row-actions" style={{display:"flex",gap:4,flexShrink:0}}>
                <Btn v="ghost" size="sm" title="Ver ficha do funcionário" onClick={()=>gerarFichaFuncionarioPDF(data,emp,showToast)}><Ic n="file" s={11}/> Ficha</Btn>
                <Btn v="ghost" size="sm" title="Limpar todos os lançamentos desta linha" onClick={()=>limparLinha(emp)}><Ic n="x" s={11}/> Limpar</Btn>
              </div>
            </div>
          </td>
          <td className="ponto-col-total" style={{textAlign:"center",fontWeight:800,fontSize:13,color:C.blue,borderTop:`1px solid ${C.line}`,fontFamily:"'Inter Display','Inter',sans-serif"}}>{equivalentes.toFixed(1).replace(".0","")}</td>
          {days.map(date=>{
            const cellKey=cellKeyFor(emp.id,date),pending=pendingCellsRef.current.has(cellKey);
            const att=attendanceFor(emp.id,date),st=att?.status,obraId=obraDoRegistro(emp,date,att),fora=!employeeRelevantOnDate(data,emp,date),feriado=feriados.includes(date);
            const foraDeLotacao=st&&obraId&&obraId!==emp.obra;   // trabalhou em obra diferente da lotação
            const aberto=obraCell===cellKey;
            return <td className="ponto-dia-cell" key={date} style={{padding:4,borderTop:`1px solid ${C.line}`,borderLeft:`1px solid ${C.line}`,background:feriado?`${C.red}06`:fora?C.surface:C.card,verticalAlign:"middle"}}>
              {fora?<div style={{textAlign:"center",color:C.muted,fontSize:11}}>—</div>:<>
                <button onClick={()=>salvarCelula(emp,date,{status:proxStatus(st)})}
                  aria-busy={pending}
                  title={pending?"Salvando...":st==="P"?"Presente":st==="M"?"Meio dia":st==="F"?"Falta":"Sem registro"}
                  style={{width:"100%",height:30,border:`1.5px solid ${st?corStatus(st):C.border}`,borderRadius:5,
                          background:st?corStatus(st):C.bg,color:st?"#fff":C.muted,
                          fontWeight:800,cursor:"pointer",fontSize:12,fontFamily:"'Inter Display','Inter',sans-serif",
                          boxShadow:pending?`0 0 0 2px ${C.blue}33`:"none",opacity:pending ? .82 : 1}}>
                  {rotuloCurto(st)}
                </button>
                {/* Obra: escondida por padrão. Mostra um chip discreto só quando a
                    obra do dia difere da lotação; toque abre a troca. */}
                {aberto ? (
                  <select autoFocus value={obraId} onChange={e=>{salvarCelula(emp,date,{obraId:e.target.value});setObraCell(null);}} onBlur={()=>setObraCell(null)}
                    style={{width:"100%",marginTop:2,border:`1px solid ${C.blue}`,borderRadius:4,background:C.bg,color:C.text,fontSize:8,padding:"2px 1px"}}>
                    <option value="">Sem obra</option>
                    {(data.obras||[]).map(o=><option key={o.id} value={o.id}>{o.name}</option>)}
                  </select>
                ) : foraDeLotacao ? (
                  <button onClick={()=>setObraCell(cellKey)} title={`Obra do dia: ${obraName(obraId)}`}
                    style={{width:"100%",marginTop:2,border:`1px solid ${C.orange}55`,background:`${C.orange}12`,color:C.orange,borderRadius:4,fontSize:7.5,fontWeight:700,cursor:"pointer",padding:"2px 1px",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>
                    {obraName(obraId)}
                  </button>
                ) : st ? (
                  <button onClick={()=>setObraCell(cellKey)} title="Trocar a obra deste dia"
                    style={{width:"100%",marginTop:2,border:0,background:"transparent",color:C.muted,borderRadius:4,fontSize:7.5,cursor:"pointer",padding:"1px",opacity:.55}}>
                    trocar obra
                  </button>
                ) : null}
              </>}
            </td>;})}
        </tr>;})}</tbody>
      </table>
      {!employees.length&&<div style={{padding:24,textAlign:"center",color:C.muted}}>Nenhum funcionário encontrado para os filtros selecionados.</div>}
    </div>

    {arqView&&(()=>{
      // Resumo do arquivo: conta P/M/F por funcionario e valora com a diaria
      // CONGELADA no snapshot (a da epoca do pagamento, nao a atual).
      const linhas=(arqView.employeesSnapshot||[]).map(e=>{
        const mapa=arqView.attendance?.[e.id]||{};
        let p=0,m=0,f=0,he=0,custo=0;
        Object.values(mapa).forEach(r=>{
          if(r?.status==="P")p++;else if(r?.status==="M")m++;else if(r?.status==="F")f++;
          const calculo=calculateAttendanceDayCost({employee:e,record:r});
          he+=calculo.overtimeHours;
          custo+=calculo.laborCost;
        });
        const dias=p+m*0.5;
        return {...e,p,m,f,he,dias,custo};
      }).sort((a,b)=>a.name.localeCompare(b.name));
      const totDias=linhas.reduce((s,l)=>s+l.dias,0);
      const totCusto=linhas.reduce((s,l)=>s+l.custo,0);
      return <Modal title={`Arquivo · ${arqView.meta?.label||quinzenaLabel}`} onClose={()=>setArqView(null)} wide>
        <p style={{fontSize:11.5,color:C.muted,marginBottom:10}}>
          Período {fmtDateFull(arqView.meta?.inicio)} a {fmtDateFull(arqView.meta?.fim)} · arquivado por {arqView.meta?.archivedBy?.nome||"-"}. Valores calculados com a diária da época (congelada no arquivo).
        </p>
        <div style={{overflow:"auto",border:`1px solid ${C.border}`,borderRadius:8}}>
          <table style={{borderCollapse:"collapse",width:"100%",fontSize:11}}>
            <thead><tr style={{background:C.surface}}>
              {["Funcionário","P","½","F","HE","Dias","Diária","Custo"].map(h=><th key={h} style={{padding:"8px 10px",textAlign:h==="Funcionário"?"left":"center",fontSize:9.5,fontWeight:800,color:C.muted,borderBottom:`1px solid ${C.border}`}}>{h}</th>)}
            </tr></thead>
            <tbody>
              {linhas.map(l=><tr key={l.id} style={{borderTop:`1px solid ${C.line}`}}>
                <td style={{padding:"7px 10px"}}><b>{l.name}</b><div style={{fontSize:9,color:C.muted}}>{l.role||"Funcionário"}</div></td>
                <td style={{textAlign:"center",color:C.green,fontWeight:800}}>{l.p}</td>
                <td style={{textAlign:"center",color:C.yellowD,fontWeight:800}}>{l.m}</td>
                <td style={{textAlign:"center",color:C.red,fontWeight:800}}>{l.f}</td>
                <td style={{textAlign:"center",color:C.purple,fontWeight:800}}>{l.he}h</td>
                <td style={{textAlign:"center",fontWeight:800}}>{l.dias.toFixed(1).replace(".0","")}</td>
                <td style={{textAlign:"center",color:C.muted}}>{fmt(l.dailyRate)}</td>
                <td style={{textAlign:"center",fontWeight:900,color:C.yellowD}}>{fmt(l.custo)}</td>
              </tr>)}
            </tbody>
            <tfoot><tr style={{background:C.surface,borderTop:`2px solid ${C.border}`}}>
              <td style={{padding:"8px 10px",fontWeight:900}}>TOTAL · {linhas.length} funcionário(s)</td>
              <td colSpan={4}></td>
              <td style={{textAlign:"center",fontWeight:900}}>{totDias.toFixed(1).replace(".0","")}</td>
              <td></td>
              <td style={{textAlign:"center",fontWeight:900,color:C.yellowD}}>{fmt(totCusto)}</td>
            </tr></tfoot>
          </table>
        </div>
        <p style={{fontSize:10,color:C.subtle,marginTop:8}}>Custo em diárias e horas extras, sem VT/VR e adiantamentos — valores congelados no arquivo.</p>
      </Modal>;
    })()}
  </div>;
}

function Ponto({ data, update, showToast, obraIdFixo="", currentUser=null, dispatchAttendanceCommand, dispatchCommand }) {
  const obraInicial=obraIdFixo||currentUser?.obraId||
    (currentUser?.role==="engenheiro"&&data.obras.length===1?data.obras[0].id:"all");
  const [selDate, setSelDate] = useState(today());
  const [filterObra, setFilterObra] = useState(obraInicial);
  const [noteModal, setNoteModal] = useState(null);
  const [noteText, setNoteText] = useState("");
  const [otModal, setOtModal] = useState(null);
  const [otHours, setOtHours] = useState("0");
  const [timeModal, setTimeModal] = useState(null);
  const [timeForm, setTimeForm] = useState({
    entrada:"", intervaloSaida:"", intervaloRetorno:"", saida:"",
  });
  const [movementModal, setMovementModal] = useState(null);
  const [unlockModal, setUnlockModal] = useState(null);
  const [lastAllDoneNotification, setLastAllDoneNotification] = useState("");
  const [expandedCard, setExpandedCard] = useState(null);   // card com "mais opções" aberto

  const activeEmployees = data.employees.filter(e =>
    e.active !== false && isEmployeeEmployedOnDate(e, today())
  );
  const dailyCheckPending = selDate === today() && activeEmployees.length > 0 && data.dailyCheckDate !== today();
  const obraName = id => data.obras.find(o => o.id === id)?.name || "-";
  const selectedObra = filterObra !== "all" ? data.obras.find(o => o.id === filterObra) : null;
  const selectedObraLocked = selectedObra ? isAttendanceLocked(data, selectedObra.id, selDate) : false;
  const selectedObraCanEdit = selectedObra ? canEditAttendance(data, selectedObra.id, selDate, currentUser?.id) : true;
  const obraAttendanceSummary = getObraAttendanceSummary(data, selDate);
  const attendanceCompletion = getAttendanceCompletionMessage(obraAttendanceSummary);
  const podeMovimentarEquipe=canManageAttendanceWorkforce(currentUser?.role);
  const obraDoPonto = employee => resolveEmployeeAttendanceObraId({
    data,employee,date:selDate,selectedObraId:filterObra,
  });
  const persistAttendanceRecord=async({employee,date=selDate,record,selectedObraId,confirmDailyCheck=false,successMessage=""})=>{
    const result=await dispatchAttendanceCommand({
      action:"attendance-upsert",operationId:pointOperationId(),
      employeeId:employee.id,date,selectedObraId,record,confirmDailyCheck,
    });
    if(!result?.ok){
      showToast(result?.reason||"A alteração de ponto não foi confirmada pelo servidor.","error");
      return false;
    }
    if(successMessage)showToast(successMessage);
    return true;
  };

  useEffect(() => {
    const notificationKey = `${selDate}__all_done`;

    if (attendanceCompletion.allDone && lastAllDoneNotification !== notificationKey) {
      showToast("Todos os pontos de todas as obras foram cadastrados!", "success");
      setLastAllDoneNotification(notificationKey);
    }
  }, [selDate, attendanceCompletion.allDone, lastAllDoneNotification, showToast]);

  const list = data.employees
    .filter(e => employeeRelevantOnDate(data, e, selDate))
    .filter(e => {
      if (filterObra === "all") return true;
      const registro = getAtt(data, e.id, selDate);
      const obraDoDia = resolveEmployeeAttendanceObraId({
        data,employee:e,date:selDate,record:registro,
      });
      return obraDoDia === filterObra;
    })
    .sort((a, b) => a.name.localeCompare(b.name));

  const requireDailyCheck = () => {
    if (!dailyCheckPending) return false;
    showToast("Antes de lançar o ponto, confirme se a equipe permanece sem alterações ou movimente o trabalhador individualmente.", "warn");
    return true;
  };

  const requireUnlocked = employee => {
    const obraId = obraDoPonto(employee);
    if (!obraId || obraId === "all") return false;
    if (canEditAttendance(data, obraId, selDate, currentUser?.id)) return false;

    setUnlockModal({ obraId, date: selDate, employee: employee || null });
    showToast("Este ponto já foi finalizado. Solicite permissão para alterar.", "warn");
    return true;
  };

  const confirmTeamWithoutChanges = async () => {
    const result=await dispatchAttendanceCommand({
      action:"attendance-daily-check",operationId:pointOperationId(),date:today(),
    });
    if(!result?.ok){showToast(result?.reason||"A equipe não foi confirmada no servidor.","error");return;}
    showToast("Equipe confirmada sem alterações.");
  };

  const finalizeObraAttendance = async () => {
    if (filterObra === "all") {
      showToast("Selecione uma obra específica para finalizar o ponto.", "error");
      return;
    }

    const obra = data.obras.find(o => o.id === filterObra);
    if (!obra) return;

    const obraSummary = getObraAttendanceSummary(data, selDate).find(o => o.obraId === filterObra);
    const missingNames = obraSummary?.missingEmployees?.map(e => e.name).join(", ") || "";
    const msg = obraSummary && obraSummary.missingCount > 0
      ? `Existem ${obraSummary.missingCount} trabalhador(es) sem registro nesta obra:\n\n${missingNames}\n\nDeseja finalizar mesmo assim?`
      : `Finalizar o ponto da obra "${obra.name}" em ${fmtDateFull(selDate)}?`;

    if (!window.confirm(`${msg}\n\nDepois disso, alterações precisarão de permissão.`)) return;

    const result=await dispatchAttendanceCommand({
      action:"attendance-lock",operationId:pointOperationId(),obraId:filterObra,date:selDate,
    });
    if(!result?.ok){showToast(result?.reason||"O ponto não foi finalizado no servidor.","error");return;}
    showToast("Ponto da obra finalizado e bloqueado.");
  };

  const setAtt = async (empId, status) => {
    const emp = data.employees.find(e => e.id === empId);
    if (requireUnlocked(emp)) return;

    // Grava EM QUAL OBRA o dia foi trabalhado.
    //
    // Antes, o custo da mão de obra era atribuído pela obra CADASTRADA no
    // funcionário. Se o pedreiro está lotado na Terras Alpha mas passou a
    // semana na Reserva, o custo inteiro dele ia para Terras Alpha - e você
    // cobrava do cliente errado. Numa empresa de administração, onde a mão de
    // obra é o maior custo e é repassada ao cliente, isso é dinheiro real
    // saindo do lugar errado.
    //
    // Agora o dia carrega a obra. Se o ponto está filtrado por uma obra, é
    // essa; senão, a obra de lotação do funcionário.
    // Se o ponto está filtrado por uma obra específica, o dia é dela.
    // Em "todas as obras", cai na lotação do funcionário - que continua sendo
    // o caso comum: cada um no seu canteiro.
    const obraDoDia = (filterObra && filterObra !== "all") ? filterObra : (emp?.obra || "");

    const next=applyAttendanceStatus({
      data,
      employeeId:empId,
      date:selDate,
      status,
      obraId:obraDoDia,
      currentDate:today(),
    });
    await persistAttendanceRecord({
      employee:emp,date:selDate,record:next.attendance?.[empId]?.[selDate],
      selectedObraId:obraDoDia,confirmDailyCheck:selDate===today(),
    });
  };

  const saveNote = async () => {
    const emp = data.employees.find(e => e.id === noteModal);
    if (requireDailyCheck()) return;
    if (requireUnlocked(emp)) return;

    const prev = getAtt(data, noteModal, selDate) || { status: null, ot: 0, note: "" };
    const ok=await persistAttendanceRecord({
      employee:emp,record:{...prev,note:noteText},
      selectedObraId:obraDoPonto(emp),confirmDailyCheck:selDate===today(),
      successMessage:"Observação salva.",
    });
    if(ok)setNoteModal(null);
  };

  const saveOT = async () => {
    const emp = data.employees.find(e => e.id === otModal);
    if (requireDailyCheck()) return;
    if (requireUnlocked(emp)) return;

    const prev = getAtt(data, otModal, selDate) || { status: null, ot: 0, note: "" };
    if (!["P","M"].includes(prev.status)) {
      showToast("Marque presença ou meio dia antes de registrar hora extra.", "error");
      return;
    }
    const horas=Number(otHours);
    if (!Number.isFinite(horas) || horas < 0 || horas > 24) {
      showToast("Informe uma quantidade de horas extras entre 0 e 24.", "error");
      return;
    }
    const ok=await persistAttendanceRecord({
      employee:emp,record:{...prev,ot:horas},
      selectedObraId:obraDoPonto(emp),confirmDailyCheck:selDate===today(),
      successMessage:"Hora extra registrada.",
    });
    if(ok)setOtModal(null);
  };

  const openTimekeeping = employee => {
    if (requireDailyCheck()) return;
    if (requireUnlocked(employee)) return;
    const record=getAtt(data,employee.id,selDate) || {};
    setTimeForm({
      entrada:record.entrada || "",
      intervaloSaida:record.intervaloSaida || "",
      intervaloRetorno:record.intervaloRetorno || "",
      saida:record.saida || "",
    });
    setTimeModal(employee.id);
  };

  const timekeepingPreview = timeModal
    ? calculateTimekeeping({
        ...timeForm,
        jornadaInicio:data.employees.find(e=>e.id===timeModal)?.workStart
          || data.config?.payrollWorkStart
          || "07:00",
      })
    : null;

  const saveTimekeeping = async () => {
    const employee=data.employees.find(e=>e.id===timeModal);
    if (!employee || requireDailyCheck() || requireUnlocked(employee)) return;
    const prev=getAtt(data,timeModal,selDate) || {status:null,ot:0,note:""};
    if (!["P","M"].includes(prev.status)) {
      showToast("Marque presença ou meio dia antes de registrar a jornada.","error");
      return;
    }
    if (!timekeepingPreview?.valid) {
      showToast(timekeepingPreview?.error || "Confira os horários informados.","error");
      return;
    }
    const ok=await persistAttendanceRecord({
      employee,selectedObraId:obraDoPonto(employee),confirmDailyCheck:selDate===today(),
      record:{
        ...prev,...timeForm,
        workedMinutes:Number(timekeepingPreview.workedMinutes||0),
        atrasoMin:Number(timekeepingPreview.delayMinutes||0),
      },
      successMessage:"Jornada registrada.",
    });
    if(ok)setTimeModal(null);
  };

  const markAll = async status => {
    if (filterObra === "all") {
      showToast("Selecione uma obra específica para marcar todos.", "error");
      return;
    }
    if (selectedObra && !selectedObraCanEdit) {
      setUnlockModal({ obraId: selectedObra.id, date: selDate, employee: null });
      showToast("Este ponto já foi finalizado. Solicite permissão para alterar.", "warn");
      return;
    }
    if (status === "F" && !window.confirm(`Marcar falta para ${list.length} trabalhador(es) de "${selectedObra?.name || "esta obra"}"?`)) {
      return;
    }

    const next=applyAttendanceStatusBatch({
      data,
      employees:list,
      date:selDate,
      status,
      obraId:filterObra,
      currentDate:today(),
    });
    const patches=list.map(employee=>({
      employeeId:employee.id,date:selDate,selectedObraId:filterObra,
      record:next.attendance?.[employee.id]?.[selDate],
    }));
    const result=await dispatchAttendanceCommand({
      action:"attendance-batch-upsert",operationId:pointOperationId(),patches,
      confirmDailyCheck:selDate===today(),
    });
    if(!result?.ok){showToast(result?.reason||"O lote de ponto não foi salvo.","error");return;}
    showToast("Ponto marcado para todos.");
  };

  const counts = { P: 0, M: 0, F: 0 };
  list.forEach(e => {
    const st = attStatus(data, e.id, selDate);
    if (st) counts[st] = (counts[st] || 0) + 1;
  });
  const semReg = Math.max(0, list.length - counts.P - counts.M - counts.F);
  const registeredCount = counts.P + counts.M + counts.F;

  return (
    <div className="anim obra-attendance">
      <PageHero
        eyebrow="Registro de ponto"
        title={selectedObra?.name || "Todas as obras"}
        description={`${fmtDateFull(selDate)} · ${registeredCount}/${list.length} lançados`}
      />

      {/* Data e obra lado a lado: a primeira decisão de quem vai lançar. */}
      <div className="obra-attendance__toolbar">
        <Inp label="Data" type="date" value={selDate} onChange={setSelDate} max={today()} />
        {obraIdFixo?<Inp label="Obra" value={data.obras.find(o=>o.id===obraIdFixo)?.name||"Obra atual"} onChange={()=>{}} disabled/>:<Sel label="Obra" value={filterObra} onChange={setFilterObra} options={[{ v: "all", l: "Todas as obras" }, ...data.obras.map(o => ({ v: o.id, l: o.name }))]} />}
      </div>

      {/* Status das pendências: uma linha quando tudo pronto; quando falta,
          lista enxuta de obras clicáveis. Sem caixas empilhadas. */}
      {attendanceCompletion.allDone ? (
        <div className="obra-attendance__notice" data-tone="success" role="status">
          <Ic n="check" s={14} color={C.green} />
          <p>Todos os pontos de {fmtDateFull(selDate)} estão lançados.</p>
        </div>
      ) : attendanceCompletion.pendingObras.length > 0 && (
        <section className="obra-attendance__pending" aria-labelledby="attendance-pending-title">
          <p id="attendance-pending-title" className="obra-attendance__pending-title">
            {attendanceCompletion.pendingObras.length} obra(s) com ponto pendente
          </p>
          {attendanceCompletion.pendingObras.map(o => (
            <button key={o.obraId} onClick={() => setFilterObra(o.obraId)}
              className="obra-attendance__pending-item"
              data-active={filterObra === o.obraId}
              aria-pressed={filterObra === o.obraId}>
              <span className="obra-attendance__pending-marker" aria-hidden="true"/>
              <span className="obra-attendance__pending-name">{o.obraName}</span>
              <span className="obra-attendance__pending-count">{o.missingCount} sem ponto</span>
            </button>
          ))}
        </section>
      )}

      {dailyCheckPending && (
        <div className="obra-attendance__daily-check">
          <div>
            <p className="obra-attendance__daily-check-title">Conferência rápida da equipe</p>
            <p>O primeiro ponto confirma a equipe automaticamente. Use esta ação somente quando não houver lançamentos hoje.</p>
          </div>
          <Btn v="ghost" size="sm" onClick={confirmTeamWithoutChanges} full>Confirmar equipe sem alterações</Btn>
        </div>
      )}

      {filterObra === "all" && (
        <p className="obra-attendance__helper">
          Em todas as obras, cada ponto vai para a obra de lotação do trabalhador. Se alguém foi emprestado a outro canteiro, filtre por aquela obra antes de marcar — o custo segue para lá. Selecione uma obra para marcar todos de uma vez e finalizar o ponto.
        </p>
      )}

      {selectedObra && (
        <div className="obra-attendance__lock-state" data-locked={selectedObraLocked}>
          <div className="obra-attendance__lock-copy">
            <Ic n={selectedObraLocked ? "lock" : "check"} s={13} color={selectedObraLocked ? C.red : C.green} />
            <span>
              {selectedObraLocked ? "Ponto finalizado e bloqueado" : "Ponto aberto para edição"}
            </span>
          </div>
          {selectedObraLocked ? (
            <Btn v="warning" size="sm" onClick={() => setUnlockModal({ obraId: selectedObra.id, date: selDate, employee: null })}><Ic n="mail" /> Solicitar permissão</Btn>
          ) : (
            <Btn size="sm" onClick={finalizeObraAttendance}><Ic n="lock" /> Finalizar ponto</Btn>
          )}
        </div>
      )}

      {/* Resumo do dia: contadores compactos numa faixa única. */}
      <section className="obra-attendance__summary" aria-label="Resumo do ponto">
        {[
          ["Presentes", counts.P, "success"],
          ["Sem registro", semReg, "neutral"],
          ["Meio dia", counts.M, "warning"],
          ["Faltas", counts.F, "danger"],
        ].map(([label, n, tone]) => (
          <div key={label} className="obra-attendance__summary-item" data-tone={tone}>
            <p className="obra-attendance__summary-value">{n}</p>
            <p className="obra-attendance__summary-label">{label}</p>
          </div>
        ))}
      </section>

      <div className="obra-attendance__bulk">
        <Btn v="success" size="sm" onClick={() => markAll("P")} disabled={filterObra==="all"||!selectedObraCanEdit||list.length===0} full title={filterObra==="all"?"Selecione uma obra para usar ações em lote":undefined}><Ic n="check" /> Todos presentes</Btn>
        <Btn v="ghost" size="sm" onClick={() => markAll("F")} disabled={filterObra==="all"||!selectedObraCanEdit||list.length===0} full title={filterObra==="all"?"Selecione uma obra para usar ações em lote":undefined} style={{color:C.red}}><Ic n="x" /> Todos com falta</Btn>
      </div>

      {list.length === 0 && <div className="obra-attendance__empty">Nenhum trabalhador ativo nesta seleção.</div>}

      <div className="obra-attendance__employees">
      {list.map(e => {
        const att = getAtt(data, e.id, selDate);
        const status = att?.status;
        const ot = Number(att?.ot || 0);
        const note = att?.note || "";
        const timekeeping=calculateTimekeeping({
          entrada:att?.entrada,
          intervaloSaida:att?.intervaloSaida,
          intervaloRetorno:att?.intervaloRetorno,
          saida:att?.saida,
          jornadaInicio:e.workStart || data.config?.payrollWorkStart || "07:00",
        });
        const obraIdPonto=obraDoPonto(e);
        const cardLocked = isAttendanceLocked(data, obraIdPonto, selDate) && !canEditAttendance(data, obraIdPonto, selDate, currentUser?.id);
        const aberto = expandedCard === e.id;

        return (
          <article key={e.id} className="obra-attendance-card" data-status={status||"empty"} data-locked={cardLocked}>
            <header className="obra-attendance-card__header">
              <div className="obra-attendance-card__identity">
                <p className="obra-attendance-card__name" title={e.name}>{e.name}</p>
                <p className="obra-attendance-card__meta">{obraName(e.obra)}{e.role ? ` · ${e.role}` : ""}</p>
              </div>
              <div className="obra-attendance-card__badges">
                {cardLocked && <Badge color={C.red}><Ic n="lock" s={10} /> Bloqueado</Badge>}
                {timekeeping.valid&&!timekeeping.empty&&<Badge color={C.blue}>{formatMinutes(timekeeping.workedMinutes)}</Badge>}
                {timekeeping.valid&&timekeeping.delayMinutes>0&&<Badge color={C.orange}>{timekeeping.delayMinutes} min atraso</Badge>}
                {ot > 0 && <Badge color={C.purple}>{ot}h extra</Badge>}
              </div>
            </header>

            {note && <p className="obra-attendance-card__note">“{note}”</p>}

            {cardLocked ? (
              <Btn v="warning" size="sm" full onClick={() => setUnlockModal({ obraId: obraIdPonto, date: selDate, employee: e })}><Ic n="mail" /> Solicitar permissão</Btn>
            ) : (
              <>
                {/* Ação principal: presença. Três botões grandes e claros. */}
                <div className="obra-attendance-card__statuses" role="group" aria-label={`Ponto de ${e.name}`}>
                  {[
                    ["P", "check", "Presente"],
                    ["M", "money", "Meio dia"],
                    ["F", "x", "Falta"],
                  ].map(([st, icon, label]) => (
                    <button key={st} type="button" onClick={() => setAtt(e.id, st)}
                      className="obra-attendance-card__status"
                      data-tone={st}
                      data-selected={status === st}
                      aria-pressed={status === st}>
                      <Ic n={icon} s={14} /> {label}
                    </button>
                  ))}
                </div>

                {/* Ações secundárias recolhidas: raras no dia a dia, não competem
                    com a marcação de presença. */}
                <button onClick={() => setExpandedCard(aberto ? null : e.id)}
                  type="button"
                  className="obra-attendance-card__more"
                  aria-expanded={aberto}>
                  {aberto ? "Menos opções" : "Mais opções"} <span aria-hidden="true">{aberto ? "▲" : "▼"}</span>
                </button>
                {aberto && (
                  <div className="obra-attendance-card__details">
                    <div className="obra-attendance-card__secondary">
                      <Btn v="ghost" size="sm" full onClick={() => openTimekeeping(e)}><Ic n="calendar" /> Jornada</Btn>
                      <Btn v="ghost" size="sm" full onClick={() => { if (requireDailyCheck()) return; if (requireUnlocked(e)) return; setOtModal(e.id); setOtHours(String(ot)); }}><Ic n="clock" /> Hora extra</Btn>
                      <Btn v="ghost" size="sm" full onClick={() => { if (requireDailyCheck()) return; if (requireUnlocked(e)) return; setNoteModal(e.id); setNoteText(note); }}><Ic n="edit" /> Observação</Btn>
                    </div>
                    {podeMovimentarEquipe && <div className="obra-attendance-card__workforce">
                      <Btn v="warning" size="sm" full onClick={() => setMovementModal({ emp: e, mode: "transfer" })}><Ic n="building" /> Transferir</Btn>
                      <Btn v="danger" size="sm" full onClick={() => setMovementModal({ emp: e, mode: "dismiss" })}><Ic n="x" /> Demitir</Btn>
                    </div>}
                  </div>
                )}
              </>
            )}
          </article>
        );
      })}
      </div>

      {movementModal && <WorkerMovementModal data={data} showToast={showToast} employee={movementModal.emp} initialMode={movementModal.mode} onClose={() => setMovementModal(null)} dispatchAttendanceCommand={dispatchAttendanceCommand} dispatchCommand={dispatchCommand} />}
      {unlockModal && <UnlockRequestModal data={data} dispatchAttendanceCommand={dispatchAttendanceCommand} showToast={showToast} obraId={unlockModal.obraId} date={unlockModal.date} employee={unlockModal.employee} onClose={() => setUnlockModal(null)} />}

      {noteModal && (
        <Modal title="Observação" onClose={() => setNoteModal(null)}>
          <Inp label="Observação" value={noteText} onChange={setNoteText} multiline />
          <div style={{ display: "flex", gap: 8, marginTop: 12 }}>
            <Btn v="ghost" onClick={() => setNoteModal(null)} full>Cancelar</Btn>
            <Btn onClick={saveNote} full><Ic n="check" /> Salvar</Btn>
          </div>
        </Modal>
      )}

      {otModal && (
        <Modal title="Horas extras" onClose={() => setOtModal(null)}>
          <Inp label="Quantidade de horas" type="number" value={otHours} onChange={setOtHours} />
          <div style={{ display: "flex", gap: 8, marginTop: 12 }}>
            <Btn v="ghost" onClick={() => setOtModal(null)} full>Cancelar</Btn>
            <Btn v="info" onClick={saveOT} full><Ic n="check" /> Registrar</Btn>
          </div>
        </Modal>
      )}

      {timeModal && (
        <Modal title="Jornada do dia" onClose={() => setTimeModal(null)}>
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
            <Inp label="Entrada" type="time" value={timeForm.entrada} onChange={v=>setTimeForm(f=>({...f,entrada:v}))}/>
            <Inp label="Saída para intervalo" type="time" value={timeForm.intervaloSaida} onChange={v=>setTimeForm(f=>({...f,intervaloSaida:v}))}/>
            <Inp label="Retorno do intervalo" type="time" value={timeForm.intervaloRetorno} onChange={v=>setTimeForm(f=>({...f,intervaloRetorno:v}))}/>
            <Inp label="Saída" type="time" value={timeForm.saida} onChange={v=>setTimeForm(f=>({...f,saida:v}))}/>
          </div>
          <div style={{marginTop:12,padding:10,border:`1px solid ${timekeepingPreview?.valid?C.border:C.red}`,borderRadius:7,background:C.surface}}>
            {timekeepingPreview?.valid
              ? <p style={{fontSize:11,fontWeight:750,color:C.text}}>
                  Total: {formatMinutes(timekeepingPreview.workedMinutes)}
                  {timekeepingPreview.delayMinutes>0?` · atraso de ${timekeepingPreview.delayMinutes} min`:" · sem atraso"}
                </p>
              : <p style={{fontSize:11,fontWeight:750,color:C.red}}>{timekeepingPreview?.error}</p>}
          </div>
          <div style={{display:"flex",gap:8,marginTop:12}}>
            <Btn v="ghost" onClick={()=>setTimeModal(null)} full>Cancelar</Btn>
            <Btn onClick={saveTimekeeping} full><Ic n="check"/> Salvar jornada</Btn>
          </div>
        </Modal>
      )}
    </div>
  );
}

